void VictoryConditions::reset(void)
{
	for (int i = 0; i < 20; ++i)
	{
		m_players[i] = NULL;
		m_isDefeated[i] = false;
	}
	m_localSlotNum = -1;
	m_cachedPlayerCount = 0;
	m_localPlayerDefeated = false;
	m_singleAllianceRemaining = false;
	m_isObserver = false;
	m_endFrame = 0;
	m_defeatedPlayerCount = 0;
	m_forceSinglePlayerDefeat = false;
	m_unk0x91 = false;
	m_victoryConditions = (TheGameLogic->m_unk0x114 == 3) + 2;
	hideEndGame();
}

// FUNCTION: BFME2 0x0041FEEB size=131 name=?hasAchievedVictory@VictoryConditions@@UAE_NPAVPlayer@@@Z evidence=N:ledger tier=B hypothesis:cohesion

// FUNCTION: BFME2 0x0041FF6E size=63 name=?hasBeenDefeated@VictoryConditions@@UAE_NPAVPlayer@@@Z evidence=N:ledger tier=A
bool VictoryConditions::hasBeenDefeated(Player *player)
{
	if (player && !player->isPlayerObserver() && m_singleAllianceRemaining && m_defeatedPlayerCount > 0 && !hasAchievedVictory(player))
		return true;
	return false;
}

// FUNCTION: BFME2 0x0041FFAD size=106 name=?cachePlayerPtrs@VictoryConditions@@UAEXXZ evidence=N:ledger tier=A
void VictoryConditions::cachePlayerPtrs(void)
{
	if (!TheRecorder->isMultiplayer())
		return;

	// cachePlayerPtr does the filtering and appending; this only counts the accepted players.
	UnsignedInt playerCount = 0;
	for (Int i = 0; i < MAX_PLAYER_COUNT; ++i)
	{
		if (cachePlayerPtr(ThePlayerList->getNthPlayer(i)))
			++playerCount;
	}
	while (playerCount < MAX_PLAYER_COUNT)
		m_players[playerCount++] = NULL;

	// With no local player there is nothing to lose: watch as an observer with the radar on.
	if (m_localSlotNum < 0)
	{
		m_localPlayerDefeated = true;
		TheRadar->forceOn(TRUE);
		m_isObserver = true;
	}
}

// FUNCTION: BFME2 0x00420017 size=120 name=?rva00420017@VictoryConditions@@UAE_NPAVPlayer@@@Z evidence=?:placeholder tier=A

// FUNCTION: BFME2 0x0042008F size=60 name=?isLocalAlliedVictory@VictoryConditions@@UAE_NXZ evidence=N:ledger tier=A
bool VictoryConditions::isLocalAlliedVictory(void)
{
	if (m_isObserver)
		return false;
	if (TheGameInfo && TheGameInfo->isSandbox())
		return false;
	if (m_localSlotNum >= 0 && (unsigned int)m_localSlotNum < 20)
		return hasAchievedVictory(m_players[m_localSlotNum]);
	return false;
}

// FUNCTION: BFME2 0x004200CB size=50 name=?isLocalAlliedDefeat@VictoryConditions@@UAE_NXZ evidence=N:ledger tier=A
bool VictoryConditions::isLocalAlliedDefeat(void)
{
	if (m_isObserver)
	{
		if (m_defeatedPlayerCount > 0)
			return m_singleAllianceRemaining;
		return false;
	}
	if (m_localSlotNum >= 0 && (unsigned int)m_localSlotNum < 20)
		return hasBeenDefeated(m_players[m_localSlotNum]);
	return false;
}

