bool VictoryConditions::hasSinglePlayerBeenDefeated(Player *player)
{
	if (player == NULL)
		return false;
	if (player->isPlayerObserver())
		return false;
	if (getForceSinglePlayerDefeat())
		return true;
	bool defeated = testDefeat(player);
	if (defeated)
		++m_defeatedPlayerCount;
	return defeated;
}

